(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.012-t*0.45)*8;
  const sx = x+wx, sy = y+wy;
  const wx2 = Math.sin(sx*0.035-t*0.6)*6 + Math.cos(sy*0.04+t*0.5)*5;
  const wy2 = Math.cos(sy*0.03+t*0.55)*6 + Math.sin(sx*0.038-t*0.65)*5;
  const sx2 = sx+wx2, sy2 = sy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1.2],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 5.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65)*90, 0.11, 2.1, 4.2],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+1)*50, 0.065, 2.4, 1.8]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for(const [sX,sY,f,sp,ph] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2=Math.sqrt((sx2-sX)**2+(sy2-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.3);
    aS2+=Math.sin(d2*f*1.4-t*sp*1.3+ph*0.7);
    iS2+=Math.sin(d2*f*0.5+t*sp*0.8+2.1-ph*0.5);
  }
  const act=aS/8, inh=iS/8, act2=aS2/8, inh2=iS2/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg2=(Math.sin(sx2*0.06-sy2*0.05+t*1.2)+Math.cos(sx2*0.045+sy2*0.035-t*0.9))/2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2=(Math.sin(dist*0.08+ang*2-t*2.1)+Math.cos(dist*0.06-ang*5+t*1.7))*0.25;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const reaction2=Math.tanh((act2-inh2*0.6+bg2*0.25+spiral2)*2.5);
  const cross=Math.tanh((reaction*reaction2+Math.sin(reaction-reaction2)*0.5)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx2*0.3+t*1.5)*Math.sin(sy2*0.28-t*1.3)*0.15;
  const blend=cross*0.5+reaction*0.2+reaction2*0.15+cell*0.1+micro*0.05;
  const v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,55,95],[18,110,130],[45,165,145],[140,195,120],[210,195,75],[230,150,60],[215,90,65],[175,50,75],[120,25,85],[60,15,65],[5,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(cross*Math.PI)*0.25;
  const edge=Math.abs(cross)>0.65?1.2:Math.abs(cross)>0.4?1.08:1.0;
  const glow=Math.max(0,cross-0.5)*0.4;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*40)|0)
  ];
}
